import{_ as a,o,c as i,ae as c}from"./chunks/framework.BZib5Ft4.js";const u=JSON.parse('{"title":"ZR-AI服务接入文档","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),d={name:"index.md"};function t(l,e,r,n,s,_){return o(),i("div",null,[...e[0]||(e[0]=[c('<h1 id="zr-ai服务接入文档" tabindex="-1">ZR-AI服务接入文档 <a class="header-anchor" href="#zr-ai服务接入文档" aria-label="Permalink to &quot;ZR-AI服务接入文档&quot;">​</a></h1><p>本应用提供统一登录门户、网站级访问控制、三方授权码换取用户身份、用户状态检查、头像和文件上传、投诉建议收集等能力。</p><h2 id="推荐接入流程" tabindex="-1">推荐接入流程 <a class="header-anchor" href="#推荐接入流程" aria-label="Permalink to &quot;推荐接入流程&quot;">​</a></h2><ol><li>管理员在门户后台创建网站服务，填写入口地址、回调地址、健康检查地址和文档地址。</li><li>三方网站在未登录时跳转到门户 <code>/login</code>，携带 <code>client_id</code>、<code>callback</code>、<code>state</code>。</li><li>门户验证用户是否有当前网站权限，通过后回调三方网站并携带一次性 <code>code</code>。</li><li>三方网站服务端用 <code>clientId + clientSecret + code</code> 请求 <code>/api/service-auth/token</code> 换取用户身份。</li><li>三方网站建立自己的本地 session，并定期调用 <code>/api/service-auth/user-status</code> 判断用户是否仍可访问。</li></ol><h2 id="用户体验能力" tabindex="-1">用户体验能力 <a class="header-anchor" href="#用户体验能力" aria-label="Permalink to &quot;用户体验能力&quot;">​</a></h2><ul><li>门户会在三方回调中携带 <code>theme</code> 和 <code>locale</code>，方便三方网站同步日夜模式和语言。</li><li>三方网站可打开 <code>/feedback?service_slug=xxx&amp;embed=1</code> 收集投诉建议。</li><li>三方网站可调用门户的头像、资料和文件上传接口，避免直接暴露对象存储凭据。</li></ul>',6)])])}const p=a(d,[["render",t]]);export{u as __pageData,p as default};
